reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {

    if (triggerType == "onStructure" || triggerType == "onStress") {
        await api.applyEffectsToTokens({
            tokens: [reactorToken],
            effectNames: {
                name: "Regen Disabled",
                icon: "systems/lancer/assets/icons/white/status_downandout.svg",
                isCustom: true
            },
            duration: {
                label: "end",
                turns: 1,
                rounds: 0,
                overrideTurnOriginId: reactorToken.id
            }
        });
        return;
    }
    const corePower = 1 + 1 * api.hasStatus(reactorToken, "core_power_active")
    const regenHP = Math.round(reactorToken.actor.system.hp.max * corePower / 4 )
    const newHP = Math.min(reactorToken.actor.system.hp.value + regenHP, reactorToken.actor.system.hp.max)
	await reactorToken.actor.update({ "system.hp.value": newHP });
    }

reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (triggerData.distanceToTrigger !== 1) {
        return false;
    };
    if (api.isHostile(reactorToken, triggerData.triggeringToken)) {
        return true;
    };
    return false;
}

reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {
	const damageRoll = 2 + 2 * api.hasStatus(reactorToken, "core_power_active")
    await api.executeDamageRoll(reactorToken, [triggerData.triggeringToken], damageRoll, "kinetic", "SCOURING SWARM")
}
